#include "PluginEditor.h"
#include "BinaryData.h"

#include <cmath>

namespace { constexpr float pi=3.14159265359f; }
void MadronAudioProcessorEditor::LuckyButton::paintButton(juce::Graphics& g,bool over,bool down){const auto b=getLocalBounds().toFloat().reduced(0.5f);const auto fg=dark_?juce::Colours::white:juce::Colour(0xff111111);const auto bg=dark_?juce::Colour(0xff0a0a0a):juce::Colours::white;g.setColour(bg);g.fillRect(b);g.setColour(fg.withAlpha(over?1.0f:0.9f));g.drawRect(b,down?1.8f:1.35f);g.setFont(font_.withHeight(16.5f));g.drawFittedText("I'm Feeling Lucky",getLocalBounds(),juce::Justification::centred,1);}
void MadronAudioProcessorEditor::ThemeButton::paintButton(juce::Graphics& g,bool over,bool){const auto fg=dark_?juce::Colours::white:juce::Colour(0xff111111);const auto bg=dark_?juce::Colour(0xff0a0a0a):juce::Colours::white;const auto r=getLocalBounds().toFloat().reduced(3.0f);g.setColour(fg.withAlpha(over?1.0f:0.9f));if(dark_){const auto c=r.getCentre();g.fillEllipse(r.reduced(8.0f));for(int i=0;i<8;++i){const float a=pi*0.25f*i;const auto a0=c+juce::Point<float>(std::cos(a),std::sin(a))*8.0f;const auto a1=c+juce::Point<float>(std::cos(a),std::sin(a))*12.0f;g.drawLine(juce::Line<float>(a0,a1),2.0f);}}else{auto moon=r.reduced(6.0f);g.fillEllipse(moon);g.setColour(bg);g.fillEllipse(moon.translated(moon.getWidth()*0.36f,-moon.getHeight()*0.18f));}}
void MadronAudioProcessorEditor::MixLookAndFeel::drawLinearSlider(juce::Graphics& g,int x,int y,int w,int h,float pos,float,float,const juce::Slider::SliderStyle,juce::Slider&){const auto fg=dark_?juce::Colours::white:juce::Colour(0xff111111);const float cy=static_cast<float>(y+h)*0.5f;g.setColour(fg.withAlpha(0.94f));g.drawLine(static_cast<float>(x),cy,static_cast<float>(x+w),cy,1.5f);g.setColour(dark_?juce::Colour(0xff0a0a0a):juce::Colours::white);g.fillEllipse(pos-6.0f,cy-6.0f,12.0f,12.0f);g.setColour(fg);g.drawEllipse(pos-6.0f,cy-6.0f,12.0f,12.0f,1.5f);}
MadronAudioProcessorEditor::MadronAudioProcessorEditor(MadronAudioProcessor& p):AudioProcessorEditor(&p),processor_(p) {auto typeface=juce::Typeface::createSystemTypefaceFor(BinaryData::GowunBatangRegular_ttf,BinaryData::GowunBatangRegular_ttfSize);font_=juce::Font(juce::FontOptions(typeface));lucky_.setDisplayFont(font_);mix_.setLookAndFeel(&mixLook_);mix_.setSliderStyle(juce::Slider::LinearHorizontal);mix_.setTextBoxStyle(juce::Slider::NoTextBox,false,0,0);mix_.setRange(0.0,1.0,0.0001);mix_.setDoubleClickReturnValue(true,0.5);mix_.setValue(processor_.globalWet(),juce::dontSendNotification);mix_.setName("Mix");mix_.setDescription("Global dry wet mix");mix_.onValueChange=[this]{processor_.setGlobalWet(static_cast<float>(mix_.getValue()));};lucky_.onClick=[this]{processor_.rollRecipe();};theme_.onClick=[this]{processor_.setThemeDark(!processor_.isThemeDark());};lucky_.setName("I'm Feeling Lucky");theme_.setName("Theme");addAndMakeVisible(lucky_);addAndMakeVisible(theme_);addAndMakeVisible(mix_);resetParticles();setSize(500,330);startTimerHz(30);}
void MadronAudioProcessorEditor::resetParticles()noexcept{for(std::size_t i=0;i<particles_.size();++i){const float q=static_cast<float>((i*37)%97)/97.0f;const bool upper=(i&1u)==0;particles_[i]={0.08f+0.84f*q,upper?-0.18f:1.08f,(q-0.5f)*0.0009f,upper?0.00045f:-0.00045f,q,static_cast<float>(i)*0.37f};}}
void MadronAudioProcessorEditor::timerCallback(){dark_=processor_.isThemeDark();const bool active=processor_.isRecipeActive();if(active&&!lastActive_)resetParticles();lastActive_=active;lucky_.setActive(active);lucky_.setDark(dark_);theme_.setDark(dark_);mixLook_.setDark(dark_);const auto hostMix=processor_.globalWet();if(std::abs(mix_.getValue()-hostMix)>0.0001)mix_.setValue(hostMix,juce::dontSendNotification);if(active)for(auto& p:particles_){p.x+=p.vx;p.y+=p.vy;p.life+=0.0022f;if(p.life>1.0f){p.life=0.0f;p.x=0.10f+0.80f*std::abs(std::sin(p.phase));p.y=(std::sin(p.phase)>0.0f)?-0.16f:1.06f;p.phase+=0.71f;}}repaint();}
void MadronAudioProcessorEditor::drawLogo(juce::Graphics& g,juce::Rectangle<float> area,juce::Colour colour)const{g.setColour(colour);g.setFont(font_.withHeight(25.0f));const juce::String text="madron";float widths[6]{};float total=0.0f;for(int i=0;i<6;++i){widths[i]=font_.getStringWidthFloat(text.substring(i,i+1));total+=widths[i];}const float tracking=8.0f,groupGap=15.0f;total+=tracking*5.0f+groupGap;float x=area.getCentreX()-total*0.5f;const float y=area.getCentreY()-font_.getHeight()*0.35f;for(int i=0;i<6;++i){g.drawText(text.substring(i,i+1),x,y,widths[i]+1.0f,font_.getHeight(),juce::Justification::centredLeft,false);x+=widths[i]+tracking+(i==2?groupGap:0.0f);}}
void MadronAudioProcessorEditor::paint(juce::Graphics& g){const auto bg=dark_?juce::Colour(0xff0a0a0a):juce::Colours::white;const auto fg=dark_?juce::Colours::white:juce::Colour(0xff111111);g.fillAll(bg);drawLogo(g,getLocalBounds().toFloat().withTop(72.0f).withHeight(68.0f),fg.withAlpha(0.96f));if(lastActive_){const auto bounds=lucky_.getBounds().toFloat();const float breath=0.5f+0.5f*std::sin(static_cast<float>(juce::Time::getMillisecondCounterHiRes()*0.001)*1.15f);for(int i=7;i>0;--i){g.setColour(fg.withAlpha((0.020f+0.014f*breath)*static_cast<float>(8-i)));g.drawRoundedRectangle(bounds.expanded(static_cast<float>(i*4)),2.0f,2.0f);}for(const auto& p:particles_){const float alpha=0.44f*(1.0f-std::abs(p.life*2.0f-1.0f));g.setColour(fg.withAlpha(alpha));g.fillEllipse(bounds.getX()+p.x*bounds.getWidth(),bounds.getY()+p.y*bounds.getHeight(),2.0f,2.0f);}}}
void MadronAudioProcessorEditor::resized(){auto r=getLocalBounds();theme_.setBounds(r.getRight()-52,12,40,40);lucky_.setBounds((getWidth()-220)/2,150,220,46);mix_.setBounds((getWidth()-220)/2,264,220,28);}
